/**
 * Entry point for Plesk / Phusion Passenger hosting.
 *
 * Why this file exists:
 * Plesk's Node.js extension runs apps through Phusion Passenger, which hands
 * the app a *unix socket path* in `process.env.PORT` (e.g. /tmp/passenger.../socket)
 * instead of a TCP port number.
 *
 * The `server.js` generated by `output: 'standalone'` does:
 *     const currentPort = parseInt(process.env.PORT, 10) || 3000
 * so a socket path becomes NaN -> 3000, the app binds to TCP 3000 and
 * Passenger can never reach it (503 / "We're sorry, but something went wrong").
 *
 * This entry point listens on whatever Passenger provides: a unix socket path
 * OR a regular TCP port (local dev / PM2).
 */
const { createServer } = require('http');
const next = require('next');

const dev = process.env.NODE_ENV === 'development';
const rawPort = process.env.PORT || '3000';
const isSocket = Number.isNaN(Number(rawPort));
const hostname = process.env.HOSTNAME || '127.0.0.1';

const app = next({
  dev,
  dir: __dirname,
  ...(isSocket ? {} : { port: Number(rawPort), hostname }),
});

const handle = app.getRequestHandler();

app
  .prepare()
  .then(() => {
    const server = createServer((req, res) => {
      handle(req, res).catch((error) => {
        console.error('[server] request failed:', error);
        if (!res.headersSent) res.statusCode = 500;
        res.end('Internal Server Error');
      });
    });

    server.on('error', (error) => {
      console.error('[server] failed to listen:', error);
      process.exit(1);
    });

    if (isSocket) {
      server.listen(rawPort, () => {
        console.log(`[server] listening on Passenger socket: ${rawPort}`);
      });
      return;
    }

    server.listen(Number(rawPort), hostname, () => {
      console.log(`[server] listening on http://${hostname}:${rawPort}`);
    });
  })
  .catch((error) => {
    console.error('[server] Next.js failed to start:', error);
    process.exit(1);
  });
